"""Temario de DataLab: 48 lecciones con práctica desde cero."""

LEVELS = ("Introducción", "Básico", "Intermedio", "Avanzado")


def lesson(level, title, concept, example, task, solution, question, options, answer, check="output"):
    return {
        "level": level,
        "title": title,
        "concept": concept,
        "example": example,
        "task": task,
        "solution": solution,
        "question": question,
        "options": options,
        "answer": answer,
        "check": check,
    }


